build/commit.go.patch:
diff --git a/build/commit.go b/build/commit.go
index c740db0..7c6c399 100644
--- a/build/commit.go
+++ b/build/commit.go
@@ -123,13 +123,7 @@ func (b *Attempt) commitApproved(ctx context.Context, ap Approved, restart bool)
 	if removalFailure != nil {
 		b.s.Puts(fmt.Sprintf("  note: could not remove the approval file %s: %s", approvalPath, removalFailure))
 	}
-	b.s.Puts(fmt.Sprintf("  repairs: %d · tokens: %s · time: %s", b.Repairs, b.Usage.Total(), duration(b.elapsed())))
-	if x := b.Executor; x != nil && x.Name != executor.Native {
-		b.s.Puts("  executor: " + x.Name + " (" + executorUsageLine(x.Usage) + ")")
-	}
-	if x := b.ReviewExecutor; x != nil {
-		b.s.Puts("  review executor: " + x.Name + " (" + executorUsageLine(x.Usage) + ")")
-	}
+	b.putSpend()
 	return false, nil
 }

@@ -143,3 +137,24 @@ func duration(d interface{ Seconds() float64 }) string {
 	}
 	return fmt.Sprintf("%ds", s)
 }
+
+// putSpend writes the Build's spend lines: repairs and time (with the native token total unless it is
+// exactly "0" while an executor line follows), the builder's executor and the review executor.
+func (b *Attempt) putSpend() {
+	builder := b.Executor
+	if builder != nil && builder.Name == executor.Native {
+		builder = nil
+	}
+	review := b.ReviewExecutor
+	tokens := " · tokens: " + b.Usage.Total()
+	if b.Usage.Total() == "0" && (builder != nil || review != nil) {
+		tokens = ""
+	}
+	b.s.Puts(fmt.Sprintf("  repairs: %d%s · time: %s", b.Repairs, tokens, duration(b.elapsed())))
+	if builder != nil {
+		b.s.Puts("  executor: " + builder.Name + " (" + executorUsageLine(builder.Usage) + ")")
+	}
+	if review != nil {
+		b.s.Puts("  review executor: " + review.Name + " (" + executorUsageLine(review.Usage) + ")")
+	}
+}

